# --- ak/dgf.f species DG multipliers (applied to the period DGPRED) ---
# AD(14), WI(21), OH(23) → 0.45; SU(22) → 0.65; all others → 1.00
ak_dgmult(sp::Int) = (sp == 14 || sp == 21 || sp == 23) ? 0.45f0 : (sp == 22 ? 0.65f0 : 1.0f0)

